1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
14	//
15	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
16	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
17	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
18	// 全部样品、保管历史以及交接编号的重复提交判断。
19	type Store struct {
20		path string
21		mu   sync.Mutex
22		data *ledger
23	
24		// now 可在同包测试中替换，便于确定性地控制事件时间。
25		now func() time.Time
26	}
27	
28	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
29	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
30	func Open(path string) (*Store, error) {
31		if strings.TrimSpace(path) == "" {
32			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
33		}
34	
35		s := &Store{path: path, now: time.Now}
36	
37		raw, err := os.ReadFile(path)
38		switch {
39		case err == nil:
40			var l ledger
41			if err := json.Unmarshal(raw, &l); err != nil {
42				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
43			}
44			if l.Version != 1 {
45				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
46			}
47			if l.Samples == nil {
48				l.Samples = make(map[string]*sampleRecord)
49			}
50			if l.Transfers == nil {
51				l.Transfers = make(map[string]*transferRecord)
52			}
53			s.data = &l
54		case os.IsNotExist(err):
55			s.data = newLedger()
56			if err := s.persist(s.data); err != nil {
57				return nil, err
58			}
59		default:
60			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
61		}
62		return s, nil
63	}
64	
65	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
66	// 避免进程中断留下半截数据。
67	func (s *Store) persist(l *ledger) error {
68		raw, err := json.MarshalIndent(l, "", "  ")
69		if err != nil {
70			return fmt.Errorf("编码本地样品数据失败: %w", err)
71		}
72	
73		dir := filepath.Dir(s.path)
74		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
75		if err != nil {
76			return fmt.Errorf("创建临时数据文件失败: %w", err)
77		}
78		tmpName := tmp.Name()
79		defer os.Remove(tmpName)
80	
81		if _, err := tmp.Write(raw); err != nil {
82			tmp.Close()
83			return fmt.Errorf("写入临时数据文件失败: %w", err)
84		}
85		if err := tmp.Close(); err != nil {
86			return fmt.Errorf("关闭临时数据文件失败: %w", err)
87		}
88		if err := os.Rename(tmpName, s.path); err != nil {
89			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
90		}
91		return nil
92	}
93	
94	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
95	// 已通过全部校验；落盘失败时内存状态保持不变。
96	func (s *Store) commit(candidate *ledger) error {
97		if err := s.persist(candidate); err != nil {
98			return err
99		}
100		s.data = candidate
101		return nil
102	}
103	
104	// RegisterInput 是登记原样的入参。
105	type RegisterInput struct {
106		// ID 为样品编号，在这份数据内唯一，去空白后非空。
107		ID string
108		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
109		Qty string
110		// Holder 为初始持有人，去空白后非空。
111		Holder string
112		// Location 为初始地点，去空白后非空。
113		Location string
114	}
115	
116	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
117	// 且不会写入任何记录。
118	func (s *Store) Register(in RegisterInput) (*Sample, error) {
119		s.mu.Lock()
120		defer s.mu.Unlock()
121	
122		id, err := trimRequired("样品编号", in.ID)
123		if err != nil {
124			return nil, err
125		}
126		holder, err := trimRequired("持有人", in.Holder)
127		if err != nil {
128			return nil, err
129		}
130		location, err := trimRequired("地点", in.Location)
131		if err != nil {
132			return nil, err
133		}
134		qty, err := parseQuantity(in.Qty)
135		if err != nil {
136			return nil, err
137		}
138		if _, exists := s.data.Samples[id]; exists {
139			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
140		}
141	
142		candidate := s.data.deepCopy()
143		now := s.now().UTC()
144		candidate.Samples[id] = &sampleRecord{
145			ID:        id,
146			Initial:   qty,
147			Remaining: qty,
148			Holder:    holder,
149			Location:  location,
150			Children:  []string{},
151			History: []historyRecord{{
152				Kind:     "register",
153				Time:     now,
154				Holder:   holder,
155				Location: location,
156				Detail:   "登记原样",
157			}},
158		}
159		if err := s.commit(candidate); err != nil {
160			return nil, err
161		}
162		return buildSampleView(candidate.Samples[id], candidate), nil
163	}
164	
165	// SplitPart 是一次分装中的一个子样。
166	type SplitPart struct {
167		// ID 为子样编号，在这份数据内唯一，去空白后非空。
168		ID string
169		// Qty 为该子样数量（毫升），大于零、最多三位小数。
170		Qty string
171	}
172	
173	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
174	type SplitInput struct {
175		// ParentID 为来源样品编号。
176		ParentID string
177		// Parts 为本次要创建的全部子样，至少一个。
178		Parts []SplitPart
179	}
180	
181	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
182	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
183	// 扣减，子样继承当时的持有人和地点，并可继续分装。
184	//
185	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
186	func (s *Store) Split(in SplitInput) (*Sample, error) {
187		s.mu.Lock()
188		defer s.mu.Unlock()
189	
190		parentID, err := trimRequired("来源样品编号", in.ParentID)
191		if err != nil {
192			return nil, err
193		}
194		if len(in.Parts) == 0 {
195			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
196		}
197	
198		parent, ok := s.data.Samples[parentID]
199		if !ok {
200			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
201		}
202	
203		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
204		type parsedPart struct {
205			id  string
206			qty int64
207		}
208		parsed := make([]parsedPart, 0, len(in.Parts))
209		seen := make(map[string]struct{}, len(in.Parts))
210		var total int64
211		for _, p := range in.Parts {
212			id, err := trimRequired("子样编号", p.ID)
213			if err != nil {
214				return nil, err
215			}
216			if _, dup := seen[id]; dup {
217				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
218			}
219			if _, exists := s.data.Samples[id]; exists {
220				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
221			}
222			if id == parentID {
223				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
224			}
225			qty, err := parseQuantity(p.Qty)
226			if err != nil {
227				return nil, err
228			}
229			seen[id] = struct{}{}
230			parsed = append(parsed, parsedPart{id: id, qty: qty})
231			total += qty
232			if total < 0 {
233				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
234			}
235		}
236	
237		if parent.Destroyed != nil {
238			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
239		}
240		if parent.PendingID != "" {
241			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
242				ErrConflict, parentID, parent.PendingID)
243		}
244		if parent.Remaining == 0 {
245			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
246		}
247		if total > parent.Remaining {
248			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
249				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
250		}
251	
252		candidate := s.data.deepCopy()
253		cpParent := candidate.Samples[parentID]
254		now := s.now().UTC()
255	
256		childIDs := make([]string, 0, len(parsed))
257		for _, p := range parsed {
258			childIDs = append(childIDs, p.id)
259			candidate.Samples[p.id] = &sampleRecord{
260				ID:        p.id,
261				ParentID:  parentID,
262				Initial:   p.qty,
263				Remaining: p.qty,
264				Holder:    cpParent.Holder,
265				Location:  cpParent.Location,
266				Children:  []string{},
267				History: []historyRecord{{
268					Kind:     "split",
269					Time:     now,
270					Holder:   cpParent.Holder,
271					Location: cpParent.Location,
272					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
273				}},
274			}
275		}
276		cpParent.Remaining -= total
277		cpParent.Children = append(cpParent.Children, childIDs...)
278		cpParent.History = append(cpParent.History, historyRecord{
279			Kind:     "split",
280			Time:     now,
281			Holder:   cpParent.Holder,
282			Location: cpParent.Location,
283			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
284		})
285	
286		if err := s.commit(candidate); err != nil {
287			return nil, err
288		}
289		return buildSampleView(cpParent, candidate), nil
290	}
291	
292	// HandoverInput 是发起交接（交出）的入参。
293	type HandoverInput struct {
294		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
295		TransferID string
296		// SampleID 为要交出的样品编号。
297		SampleID string
298		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
299		FromHolder string
300		// FromLocation 为交出地点，必须与样品当前地点完全一致。
301		FromLocation string
302		// ToHolder 为指定接收人，不能与交出人相同。
303		ToHolder string
304		// ToLocation 为目的地点。
305		ToLocation string
306		// HandedOverAt 为交出时间。
307		HandedOverAt time.Time
308	}
309	
310	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
311	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
312	//
313	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
314	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
315	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
316		s.mu.Lock()
317		defer s.mu.Unlock()
318	
319		transferID, err := trimRequired("交接编号", in.TransferID)
320		if err != nil {
321			return nil, err
322		}
323		sampleID, err := trimRequired("样品编号", in.SampleID)
324		if err != nil {
325			return nil, err
326		}
327		fromHolder, err := trimRequired("交出人", in.FromHolder)
328		if err != nil {
329			return nil, err
330		}
331		fromLocation, err := trimRequired("交出地点", in.FromLocation)
332		if err != nil {
333			return nil, err
334		}
335		toHolder, err := trimRequired("接收人", in.ToHolder)
336		if err != nil {
337			return nil, err
338		}
339		toLocation, err := trimRequired("目的地点", in.ToLocation)
340		if err != nil {
341			return nil, err
342		}
343		if in.HandedOverAt.IsZero() {
344			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
345		}
346		handedAt := in.HandedOverAt.UTC()
347	
348		if existing, ok := s.data.Transfers[transferID]; ok {
349			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
350				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
351			}
352			// 完全相同的重复提交：返回原交接，不增加任何记录。
353			return buildTransferView(existing), nil
354		}
355	
356		sample, ok := s.data.Samples[sampleID]
357		if !ok {
358			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
359		}
360		if sample.Destroyed != nil {
361			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
362		}
363		if sample.Remaining == 0 {
364			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
365		}
366		if sample.PendingID != "" {
367			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
368				ErrConflict, sampleID, sample.PendingID)
369		}
370		if sample.Holder != fromHolder {
371			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
372				ErrInvalid, fromHolder, sampleID, sample.Holder)
373		}
374		if sample.Location != fromLocation {
375			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
376				ErrInvalid, fromLocation, sampleID, sample.Location)
377		}
378		if toHolder == fromHolder {
379			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
380		}
381	
382		candidate := s.data.deepCopy()
383		rec := &transferRecord{
384			ID:           transferID,
385			SampleID:     sampleID,
386			FromHolder:   fromHolder,
387			FromLocation: fromLocation,
388			ToHolder:     toHolder,
389			ToLocation:   toLocation,
390			Qty:          sample.Remaining,
391			HandedOverAt: handedAt,
392		}
393		candidate.Transfers[transferID] = rec
394		cpSample := candidate.Samples[sampleID]
395		cpSample.PendingID = transferID
396		cpSample.History = append(cpSample.History, historyRecord{
397			Kind:     "transfer-out",
398			Time:     handedAt,
399			Holder:   fromHolder,
400			Location: fromLocation,
401			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
402		})
403	
404		if err := s.commit(candidate); err != nil {
405			return nil, err
406		}
407		return buildTransferView(rec), nil
408	}
409	
410	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
411	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
412		return t.SampleID == sampleID &&
413			t.FromHolder == fromHolder &&
414			t.FromLocation == fromLocation &&
415			t.ToHolder == toHolder &&
416			t.ToLocation == toLocation &&
417			t.HandedOverAt.Equal(handedAt)
418	}
419	
420	// ConfirmInput 是确认接收的入参。
421	type ConfirmInput struct {
422		// TransferID 为待确认的交接编号。
423		TransferID string
424		// Receiver 为实际接收人，必须是发起时指定的接收人。
425		Receiver string
426		// AtLocation 为接收地点，必须是发起时的目的地点。
427		AtLocation string
428		// ReceivedAt 为接收时间，不能早于交出时间。
429		ReceivedAt time.Time
430	}
431	
432	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
433	// 才真正改变，待确认状态结束。
434	//
435	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
436	// 返回原结果且不增加转手记录；信息不同则拒绝。
437	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
438		s.mu.Lock()
439		defer s.mu.Unlock()
440	
441		transferID, err := trimRequired("交接编号", in.TransferID)
442		if err != nil {
443			return nil, err
444		}
445		receiver, err := trimRequired("接收人", in.Receiver)
446		if err != nil {
447			return nil, err
448		}
449		atLocation, err := trimRequired("接收地点", in.AtLocation)
450		if err != nil {
451			return nil, err
452		}
453		if in.ReceivedAt.IsZero() {
454			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
455		}
456		receivedAt := in.ReceivedAt.UTC()
457	
458		rec, ok := s.data.Transfers[transferID]
459		if !ok {
460			// 明确的不存在错误，绝不顺带创建交接。
461			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
462		}
463	
464		if rec.Confirmed {
465			same := rec.ConfirmedBy == receiver &&
466				rec.ToLocation == atLocation &&
467				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
468			if !same {
469				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
470			}
471			return buildTransferView(rec), nil
472		}
473	
474		if receiver != rec.ToHolder {
475			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
476				ErrConflict, rec.ToHolder, transferID, receiver)
477		}
478		if atLocation != rec.ToLocation {
479			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
480				ErrConflict, rec.ToLocation, transferID, atLocation)
481		}
482		if receivedAt.Before(rec.HandedOverAt) {
483			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
484				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
485		}
486	
487		candidate := s.data.deepCopy()
488		cp := candidate.Transfers[transferID]
489		cp.Confirmed = true
490		cp.ConfirmedBy = receiver
491		receivedAtCopy := receivedAt
492		cp.ReceivedAt = &receivedAtCopy
493	
494		sample := candidate.Samples[cp.SampleID]
495		sample.Holder = receiver
496		sample.Location = atLocation
497		sample.PendingID = ""
498		sample.History = append(sample.History, historyRecord{
499			Kind:     "transfer-in",
500			Time:     receivedAt,
501			Holder:   receiver,
502			Location: atLocation,
503			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
504		})
505	
506		if err := s.commit(candidate); err != nil {
507			return nil, err
508		}
509		return buildTransferView(cp), nil
510	}
511	
512	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
513	type DestroyInput struct {
514		// SampleID 为样品编号。
515		SampleID string
516		// Operator 为操作人，去空白后必须与样品当前持有人一致。
517		Operator string
518		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
519		Location string
520		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
521		At time.Time
522		// Reason 为销毁原因，去空白后非空。
523		Reason string
524	}
525	
526	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
527	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
528	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
529	// 事件；返回该样品的最新查询结果。
530	//
531	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
532	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
533	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
534	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
535		s.mu.Lock()
536		defer s.mu.Unlock()
537	
538		sampleID, err := trimRequired("样品编号", in.SampleID)
539		if err != nil {
540			return nil, err
541		}
542		operator, err := trimRequired("操作人", in.Operator)
543		if err != nil {
544			return nil, err
545		}
546		location, err := trimRequired("所在地点", in.Location)
547		if err != nil {
548			return nil, err
549		}
550		reason, err := trimRequired("销毁原因", in.Reason)
551		if err != nil {
552			return nil, err
553		}
554		if in.At.IsZero() {
555			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
556		}
557		at := in.At.UTC()
558	
559		rec, ok := s.data.Samples[sampleID]
560		if !ok {
561			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
562		}
563	
564		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
565		if rec.Destroyed != nil {
566			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
567				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
568					ErrConflict, sampleID)
569			}
570			return buildSampleView(rec, s.data), nil
571		}
572	
573		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
574		if operator != rec.Holder {
575			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
576				ErrConflict, operator, sampleID, rec.Holder)
577		}
578		if location != rec.Location {
579			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
580				ErrConflict, location, sampleID, rec.Location)
581		}
582		if rec.PendingID != "" {
583			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
584				ErrConflict, sampleID, rec.PendingID)
585		}
586		if rec.Remaining == 0 {
587			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
588				ErrConflict, sampleID)
589		}
590		for _, h := range rec.History {
591			if at.Before(h.Time) {
592				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
593					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
594			}
595		}
596	
597		candidate := s.data.deepCopy()
598		cp := candidate.Samples[sampleID]
599		destroyedQty := cp.Remaining
600		cp.Remaining = 0
601		cp.Destroyed = &destructionRecord{
602			Operator: operator,
603			Location: location,
604			At:       at,
605			Reason:   reason,
606			Qty:      destroyedQty,
607		}
608		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
609		cp.History = append(cp.History, historyRecord{
610			Kind:     "destroy",
611			Time:     at,
612			Holder:   operator,
613			Location: location,
614			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
615		})
616	
617		if err := s.commit(candidate); err != nil {
618			return nil, err
619		}
620		return buildSampleView(cp, candidate), nil
621	}
622	
623	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
624	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
625	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
626		return d.Operator == operator &&
627			d.Location == location &&
628			d.At.Equal(at) &&
629			d.Reason == reason
630	}
631	
632	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
633	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
634	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
635	func (s *Store) GetSample(id string) (*Sample, error) {
636		s.mu.Lock()
637		defer s.mu.Unlock()
638	
639		sampleID, err := trimRequired("样品编号", id)
640		if err != nil {
641			return nil, err
642		}
643		rec, ok := s.data.Samples[sampleID]
644		if !ok {
645			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
646		}
647		return buildSampleView(rec, s.data), nil
648	}
649	
650	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
651	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
652	func (s *Store) GetTransfer(id string) (*TransferView, error) {
653		s.mu.Lock()
654		defer s.mu.Unlock()
655	
656		transferID, err := trimRequired("交接编号", id)
657		if err != nil {
658			return nil, err
659		}
660		rec, ok := s.data.Transfers[transferID]
661		if !ok {
662			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
663		}
664		return buildTransferView(rec), nil
665	}
666	
667	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
668	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
669		children := append([]string{}, r.Children...)
670		history := make([]History, 0, len(r.History))
671		for _, h := range r.History {
672			history = append(history, History{
673				Kind:     h.Kind,
674				Time:     h.Time,
675				Holder:   h.Holder,
676				Location: h.Location,
677				Detail:   h.Detail,
678			})
679		}
680		v := &Sample{
681			ID:         r.ID,
682			ParentID:   r.ParentID,
683			InitialQty: formatUnits(r.Initial),
684			Remaining:  formatUnits(r.Remaining),
685			Holder:     r.Holder,
686			Location:   r.Location,
687			Children:   children,
688			History:    history,
689		}
690		if r.PendingID != "" {
691			if t, ok := l.Transfers[r.PendingID]; ok {
692				v.PendingTransfer = buildTransferView(t)
693			}
694		}
695		if r.Destroyed != nil {
696			v.Destruction = &Destruction{
697				Operator: r.Destroyed.Operator,
698				Location: r.Destroyed.Location,
699				At:       r.Destroyed.At,
700				Reason:   r.Destroyed.Reason,
701				Qty:      formatUnits(r.Destroyed.Qty),
702			}
703		}
704		return v
705	}
706	
707	// buildTransferView 把内部交接记录转换为对外视图。
708	func buildTransferView(r *transferRecord) *TransferView {
709		v := &TransferView{
710			TransferID:   r.ID,
711			SampleID:     r.SampleID,
712			FromHolder:   r.FromHolder,
713			FromLocation: r.FromLocation,
714			ToHolder:     r.ToHolder,
715			ToLocation:   r.ToLocation,
716			Qty:          formatUnits(r.Qty),
717			HandedOverAt: r.HandedOverAt,
718			Confirmed:    r.Confirmed,
719			ConfirmedBy:  r.ConfirmedBy,
720		}
721		if r.ReceivedAt != nil {
722			rx := *r.ReceivedAt
723			v.ReceivedAt = &rx
724			v.ConfirmedAt = r.ToLocation
725		}
726		return v
727	}
