57	
58		cases := []struct {
59			name string
60			in   RegisterInput
61			want error
62		}{
63			{"空白编号", RegisterInput{ID: "   ", Qty: "1", Holder: "h", Location: "l"}, ErrInvalid},
64			{"空白持有人", RegisterInput{ID: "S2", Qty: "1", Holder: " ", Location: "l"}, ErrInvalid},
65			{"空白地点", RegisterInput{ID: "S2", Qty: "1", Holder: "h", Location: ""}, ErrInvalid},
66			{"零数量", RegisterInput{ID: "S2", Qty: "0", Holder: "h", Location: "l"}, ErrInvalid},
67			{"负数量", RegisterInput{ID: "S2", Qty: "-1", Holder: "h", Location: "l"}, ErrInvalid},
68			{"四位小数", RegisterInput{ID: "S2", Qty: "1.0001", Holder: "h", Location: "l"}, ErrInvalid},
69			{"非数字", RegisterInput{ID: "S2", Qty: "abc", Holder: "h", Location: "l"}, ErrInvalid},
70			{"科学计数", RegisterInput{ID: "S2", Qty: "1e3", Holder: "h", Location: "l"}, ErrInvalid},
71			{"点开头", RegisterInput{ID: "S2", Qty: ".5", Holder: "h", Location: "l"}, ErrInvalid},
72			{"重复编号", RegisterInput{ID: "S1", Qty: "1", Holder: "h", Location: "l"}, ErrConflict},
73		}
74		for _, c := range cases {
75			t.Run(c.name, func(t *testing.T) {
