232	func TestHandoverLifecycle(t *testing.T) {
233		s, _ := fixedStore(t)
234		mustRegister(t, s, "P", "4.250", "张三", "实验室A")
235		hAt := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
236		rAt := hAt.Add(time.Hour)
237	
238		in := HandoverInput{
239			TransferID: "TR-1", SampleID: "P",
240			FromHolder: "张三", FromLocation: "实验室A",
241			ToHolder: "李四", ToLocation: "实验室B",
