420	
421		// 已确认后接收信息不同 → 拒绝。
422		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "B", at.Add(2 * time.Hour)}); !errors.Is(err, ErrConflict) {
423			t.Fatalf("不同接收时间应拒绝, got %v", err)
424		}
