				t.Fatal(err)
			}
			if !reflect.DeepEqual(reopenedExisting, f.existingBefore) {
				t.Fatalf("重开后原有子样应保持独立状态:\n before=%+v\n after =%+v",
					f.existingBefore, reopenedExisting)
			}
		})
	}
}

